import{factorData}from './photo-models.js?v=20261023-physicscomplete01';
const mat=(T,c,e={})=>new T.MeshStandardMaterial({color:c,roughness:.3,metalness:.03,...e});
function ball(g,T,x,y,z,r,c,scale=[1,1,1],name=''){let m=new T.Mesh(new T.SphereGeometry(r,24,18),mat(T,c));m.position.set(x,y,z);m.scale.set(...scale);m.name=name;g.add(m);return m;}
function box(g,T,x,y,z,a,b,c,color,name=''){let m=new T.Mesh(new T.BoxGeometry(a,b,c),mat(T,color));m.position.set(x,y,z);m.name=name;g.add(m);return m;}
function rod(g,T,a,b,r,c,name=''){let p=new T.Vector3(...a),q=new T.Vector3(...b),v=q.clone().sub(p),m=new T.Mesh(new T.CylinderGeometry(r,r,v.length(),16),mat(T,c));m.position.copy(p.add(q).multiplyScalar(.5));m.quaternion.setFromUnitVectors(new T.Vector3(0,1,0),v.normalize());m.name=name;g.add(m);return m;}
function plant(g,T,x=0,y=-1.1,small=1){rod(g,T,[x,y,0],[x,y+2*small,0],.035,0x8fa98e,'plant-stem');for(let i=0;i<5;i++){let side=i%2?1:-1,l=ball(g,T,x+side*.3*small,y+.3*small+i*.3*small,0,.3*small,0x9db6a0,[1.3,.45,.4],'plant-leaf');l.rotation.z=side*.4;}}
function lamp(g,T,x=-1.7){rod(g,T,[x,-1.3,0],[x,1,0],.035,0xb6c7c7,'lamp-stand');box(g,T,x,-1.35,0,.65,.08,.5,0xb2bfc0);let m=new T.Mesh(new T.ConeGeometry(.35,.5,32,1,true),mat(T,0xd3b69a,{side:T.DoubleSide}));m.rotation.z=Math.PI/2;m.position.set(x+.2,1,0);m.name='lamp';g.add(m);}
function chloroplast(g,T,w){let f=w.factor,idx=w.index??2,d=factorData[f],rate=d?.y[idx]??(w.state==='dark'?0:6),light=w.state!=='dark'&&(f!=='light'||idx>0),pigment=f==='chlorophyll'?d.x[idx]/100:1;let shell=new T.Mesh(new T.SphereGeometry(1.1,48,32,0,Math.PI*2,Math.PI*.35,Math.PI*.65),mat(T,0xa8bca6,{side:T.DoubleSide}));shell.rotation.x=Math.PI/2;shell.scale.set(1.65,.8,.75);shell.name='chloroplast-envelope-cutaway';g.add(shell);for(let x of[-1,0,1]){for(let j=0;j<5;j++){let disc=new T.Mesh(new T.CylinderGeometry(.3,.3,.075,32),mat(T,pigment>.3?0x789c86:0xb2b7a0));disc.position.set(x,-.25+j*.12,.08);disc.name='granum-disc';g.add(disc);}if(x<1)rod(g,T,[x+.28,-.01,.08],[x+.72,-.01,.08],.035,0x92ae94,'lamella');}for(let i=0;i<Math.round(12*pigment);i++)ball(g,T,-1.15+(i%6)*.45,.4+Math.floor(i/6)*.14,.35,.035,0x436e5d,[1,1,1],'chlorophyll-marker');if(light)for(let i=0;i<4;i++)rod(g,T,[-1.5+i*.8,1.3,-.1],[-1.15+i*.7,.55,0],.018,0xf0ce99,'light-ray');for(let i=0;i<Math.round(rate);i++)ball(g,T,-1.3+i*.4,-.95+(i%2)*.18,.3,.065,0x9cc6ce,[1,1,1],'rate-marker');}
export function buildPhoto(g,T,w={}){let kind=w.kind||'chloroplast',s=w.state||'light';if(['chloroplast','factor'].includes(kind)){chloroplast(g,T,w);return;}
if(kind==='ledger'){let after=s==='after'||w.after;if(after){for(let i=0;i<24;i++)ball(g,T,-1.3+(i%4)*.25,-.5+Math.floor(i/4)*.22,0,.085,i<6?0xb9c8ca:i<18?0xefe1c3:0xd79d8c,[1,1,1],i<6?'C':i<18?'H':'O');for(let i=0;i<12;i++)ball(g,T,.4+(i%4)*.27,-.4+Math.floor(i/4)*.38,0,.085,0xd79d8c,[1,1,1],'O');}else for(let i=0;i<6;i++){let x=-1.45+(i%3)*1.35,y=.5-Math.floor(i/3)*1.1;ball(g,T,x,y,0,.09,0xb9c8ca,[1,1,1],'C');for(let side of[-1,1])ball(g,T,x+side*.2,y,0,.085,0xd79d8c,[1,1,1],'O');ball(g,T,x,y-.45,0,.085,0xd79d8c,[1,1,1],'O');for(let side of[-1,1])ball(g,T,x+side*.17,y-.62,0,.055,0xefe1c3,[1,1,1],'H');}return;}
if(['apparatus','lamp','bubbles'].includes(kind)){let distance=w.distance??20,xLamp=-1.1-(distance-10)/30*.9;lamp(g,T,xLamp);let jar=new T.Mesh(new T.CylinderGeometry(.7,.7,1.65,40,1,true),mat(T,0xb8d1d1,{transparent:true,opacity:.22,side:T.DoubleSide}));jar.position.set(.8,-.25,0);jar.name='water-beaker';g.add(jar);let water=new T.Mesh(new T.CylinderGeometry(.66,.66,1.2,40),mat(T,0x93bcc4,{transparent:true,opacity:.15}));water.position.set(.8,-.45,0);g.add(water);plant(g,T,.8,-1,.65);rod(g,T,[.8,.35,0],[.8,1.2,0],.035,0xc6d5cf,'gas-outlet');let collector=new T.Mesh(new T.CylinderGeometry(.14,.14,.9,32,1,true),mat(T,0xc5d5d0,{transparent:true,opacity:.5,side:T.DoubleSide}));collector.position.set(.8,1.15,0);collector.name='gas-collector';g.add(collector);let volume=Math.max(0,Math.min(13,Number(w.volume)||0));if(volume>0){let gas=new T.Mesh(new T.CylinderGeometry(.11,.11,.7*volume/13,24),mat(T,0xe3d1aa));gas.position.set(.8,1.55-.35*volume/13,0);gas.name='collected-gas';g.add(gas);}for(let i=0;i<(kind==='bubbles'?10:3);i++)ball(g,T,.7+(i%2)*.16,-.25+i*.15,.3,kind==='bubbles'?(s==='large'?.09:.045):.045,0xb6d4d7,[1,1,1],'oxygen-bubble');box(g,T,0,-1.45,.5,4,.04,.2,0xd3c4aa,'distance-ruler');return;}
if(['greenhouse','limits'].includes(kind)){for(let x of[-1.6,1.6])for(let z of[-.8,.8])rod(g,T,[x,-1.3,z],[x,.9,z],.035,0xc3d2cd,'greenhouse-frame');for(let z of[-.8,.8]){rod(g,T,[-1.6,.9,z],[0,1.65,z],.035,0xc3d2cd);rod(g,T,[0,1.65,z],[1.6,.9,z],.035,0xc3d2cd);}let roof=new T.Mesh(new T.BoxGeometry(3.2,2.15,1.6),mat(T,0xb8d1ce,{transparent:true,opacity:.08}));roof.position.y=-.2;g.add(roof);plant(g,T,-.7,-1.3,.8);plant(g,T,.6,-1.3,.8);let plan=w.plan||s;if(['light','all'].includes(plan)||kind==='limits')for(let x of[-.8,.8]){ball(g,T,x,1.1,0,.14,0xf0cea1);rod(g,T,[x,.95,0],[x,.45,0],.015,0xf0cea1,'light-ray');}if(['co2','all'].includes(plan)||s==='co2')for(let i=0;i<7;i++)ball(g,T,-1.2+i*.4,.35+(i%2)*.3,.55,.045,0xc5cdd0,[1,1,1],'co2-marker');if(['heat','all'].includes(plan)||s==='temperature')box(g,T,1,-1,.2,.4,.5,.4,0xd8aa91,'heater');return;}
if(kind==='uses'){if(s==='cellulose'){for(let row=0;row<3;row++)for(let i=0;i<8;i++)ball(g,T,-1.5+i*.43,-.6+row*.6,0,.16,0xc2baa0,[1,1,1],'cellulose-unit');}else if(s==='starch'){for(let i=0;i<18;i++)ball(g,T,Math.sin(i*2)*(.25+i*.045),Math.cos(i*2)*(.25+i*.045),0,.15,0xd8c5a3,[1,1,1],'storage-unit');}else if(s==='oil'){for(let i=0;i<5;i++)ball(g,T,-1.2+(i%3)*1.1,-.4+Math.floor(i/3)*.9,0,.35,0xd9b18d,[1,1.15,1],'oil-droplet');}else if(['protein','nitrate-on','nitrate-off'].includes(s)){for(let i=0;i<(s==='nitrate-off'?2:10);i++)ball(g,T,-1.4+i*.3,Math.sin(i)*.3,0,.16,0xa8bcb6,[1,1,1],'amino-acid-unit');for(let i=0;i<(s==='nitrate-off'?0:4);i++)ball(g,T,-.7+i*.45,.9,0,.1,0xc99e91,[1,1,1],'nitrate-symbol');}else{let m=ball(g,T,0,0,0,1,0xb8aaa1,[1.7,.75,.65],'respiration-organelle-symbol');for(let i=0;i<5;i++)rod(g,T,[-1+i*.5,-.3,.6],[-.85+i*.5,.3,.6],.04,0xe7c9a7,'fold-symbol');if(s==='day')for(let i=0;i<3;i++)rod(g,T,[-1+i,1.3,0],[-.8+i,.6,0],.02,0xe6ca9c,'light-ray');}return;}
}
